-- GERADO por db/seed/expo.mjs — não edite à mão. Cenário ILUSTRATIVO / dados sintéticos.
SET DEFINE OFF
DECLARE v_ev NUMBER; BEGIN
  SELECT MAX(id) INTO v_ev FROM ac_evento WHERE codigo = 'EXPO26';
  IF v_ev IS NOT NULL THEN
    DELETE FROM ac_reporte WHERE evento_id = v_ev;
    DELETE FROM ac_trecho  WHERE evento_id = v_ev;
    DELETE FROM ac_ponto   WHERE evento_id = v_ev;
    DELETE FROM ac_area    WHERE evento_id = v_ev;
    DELETE FROM ac_evento  WHERE id = v_ev;
  END IF;
  COMMIT;
END;
/
MERGE INTO ac_perfil t USING (SELECT 'PADRAO' codigo, 'Sem restrição' nome, 'N' evita_escada, 1 peso_ruido, 1 peso_lotacao, 1.3 velocidade_ms, 'Caminho mais curto, evitando só o que está muito cheio.' descricao FROM dual
  UNION ALL SELECT 'CADEIRANTE' codigo, 'Cadeirante / carrinho de bebê' nome, 'S' evita_escada, 1 peso_ruido, 4 peso_lotacao, 1 velocidade_ms, 'Sem escadas nem degraus; foge de multidão, onde a cadeira não passa.' descricao FROM dual
  UNION ALL SELECT 'MOBILIDADE' codigo, 'Muletas / mobilidade reduzida' nome, 'S' evita_escada, 1 peso_ruido, 3 peso_lotacao, 0.7 velocidade_ms, 'Sem escadas; prefere trechos com menos gente.' descricao FROM dual
  UNION ALL SELECT 'NEURODIVERGENTE' codigo, 'Neurodivergente / sensível a estímulos' nome, 'N' evita_escada, 6 peso_ruido, 5 peso_lotacao, 1.2 velocidade_ms, 'Prioriza silêncio e pouca gente, mesmo que o caminho seja mais longo.' descricao FROM dual) s
ON (t.codigo = s.codigo)
WHEN MATCHED THEN UPDATE SET t.nome=s.nome, t.evita_escada=s.evita_escada, t.peso_ruido=s.peso_ruido, t.peso_lotacao=s.peso_lotacao, t.velocidade_ms=s.velocidade_ms, t.descricao=s.descricao
WHEN NOT MATCHED THEN INSERT (codigo,nome,evita_escada,peso_ruido,peso_lotacao,velocidade_ms,descricao) VALUES (s.codigo,s.nome,s.evita_escada,s.peso_ruido,s.peso_lotacao,s.velocidade_ms,s.descricao);
COMMIT;
